//! The schema descriptor the strip reads (Phase 85, D-12): the zod schemas the TS migration chains
//! strip against, as data.
//!
//! `schemas.json` is generated by `meta/genStoreSchemas.ts` from the very zod schemas
//! `storeMigrations/schemaStrip.ts` reads at call time, and a jest drift test fails when it differs
//! from a fresh generation. Nothing here is a hand-copied key list. The grammar is the part of zod the
//! strip and `safeParse` need and no more; the generator refuses anything else.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// How an object treats keys it does not declare. `Loose` is both `z.looseObject` and a plain
/// `z.object`: unknown keys are accepted, and the strip leaves the object alone.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    Strict,
    Loose,
}

/// One declared object member. `optional` is zod's own verdict for `undefined`, which is the
/// question the strip asks of a member.
#[derive(Debug, Deserialize)]
pub struct Member {
    pub optional: bool,
    pub node: Node,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum Node {
    Object {
        mode: Mode,
        members: HashMap<String, Member>,
    },
    Array {
        element: Box<Node>,
        min: Option<usize>,
        max: Option<usize>,
    },
    Record {
        value: Box<Node>,
    },
    Union {
        options: Vec<Node>,
    },
    Literal {
        value: String,
    },
    Enum {
        values: Vec<String>,
    },
    String {
        min: Option<usize>,
        max: Option<usize>,
    },
    Number,
    Boolean,
    Null,
    Optional {
        inner: Box<Node>,
    },
    Nullable {
        inner: Box<Node>,
    },
    Default {
        inner: Box<Node>,
    },
}

/// The five per-runner `GameInfo` schemas.
#[derive(Debug, Deserialize)]
pub struct GameInfo {
    pub steam: Node,
    pub gog: Node,
    pub legendary: Node,
    pub nile: Node,
    pub sideload: Node,
}

impl GameInfo {
    /// The schema for a runner name, `None` for a runner no schema exists for.
    pub fn for_runner(&self, runner: &str) -> Option<&Node> {
        match runner {
            "steam" => Some(&self.steam),
            "gog" => Some(&self.gog),
            "legendary" => Some(&self.legendary),
            "nile" => Some(&self.nile),
            "sideload" => Some(&self.sideload),
            _ => None,
        }
    }
}

/// The `install` members the gog and sideload `installed` lists are stripped against.
#[derive(Debug, Deserialize)]
pub struct GameInfoInstalled {
    pub gog: Node,
    pub sideload: Node,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Schemas {
    /// `appSettingsSchema.partial()`.
    pub settings_global: Node,
    /// `gameSettingsSchema.partial()`.
    pub settings_game: Node,
    pub game_info: GameInfo,
    pub game_info_installed: GameInfoInstalled,
}

/// The descriptor, parsed once from the compiled-in `schemas.json`.
pub fn schemas() -> &'static Schemas {
    static SCHEMAS: OnceLock<Schemas> = OnceLock::new();
    SCHEMAS.get_or_init(|| {
        serde_json::from_str(include_str!("schemas.json"))
            .expect("schemas.json is generated by meta/genStoreSchemas.ts and always parses")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_descriptor_parses_and_names_every_schema() {
        let s = schemas();
        for node in [&s.settings_global, &s.settings_game] {
            let Node::Object { mode, members } = node else {
                panic!("a settings schema is an object");
            };
            assert_eq!(*mode, Mode::Strict);
            assert!(members.values().all(|m| m.optional), "partial");
        }
        for runner in ["steam", "gog", "legendary", "nile", "sideload"] {
            assert!(s.game_info.for_runner(runner).is_some(), "{runner}");
        }
        assert!(s.game_info.for_runner("humble").is_none());
        assert!(matches!(
            s.game_info_installed.gog,
            Node::Object {
                mode: Mode::Strict,
                ..
            }
        ));
    }
}
